/// <summary>
/// Display method for laod pick complete
/// </summary>
/// <returns>Boolean value</returns>
public display NoYesId displayLoadPickComplete()
{
    METSalesOrderShipmentLoadHeader     shipmentLoadHeader;

        select firstonly RecId from shipmentLoadHeader
            where shipmentLoadHeader.LoadId == this.LoadId
                && shipmentLoadHeader.ShipmentPickComplete == NoYes::No;

        if (shipmentLoadHeader.RecId != 0)
        {
            return NoYes::No;
        }
        else
        {
            return NoYes::Yes;
        }

}

/// <summary>
/// Display method for laod pick complete
/// </summary>
/// <returns>Boolean value</returns>
public display NoYesId displayLoadPickComplete_Old()
{
    WMSPickingRoute                     wmsPickingRoute;
    METSalesOrderShipmentLoadLines      shipmentLoadLines;
    METSalesOrderShipmentLoadHeader     shipmentLoadHeader;
    SalesTable                          salesTable;
    METSalesTable                       metSalesTable;


    select firstonly RecId from wmsPickingRoute
            where wmsPickingRoute.expeditionStatus != WMSExpeditionStatus::Complete
        exists join shipmentLoadLines
            where   shipmentLoadLines.PickingListNum == wmsPickingRoute.pickingRouteID 
        exists join shipmentLoadHeader 
            where shipmentLoadLines.ShipmentId == shipmentLoadHeader.ShipmentId &&
                shipmentLoadHeader.LoadId == this.LoadId;  

    if (wmsPickingRoute.RecId != 0)
    {
        return NoYes::No;
    }
    else
    {
        // Bug 303846: CB177 Shipment & Load pick complete = Yes when not all lines completed
        // If an intercompany SO picking list with the same sales order number is not completed or cancelled, then return No
        if (this.TransactionType == METOrderTransactionType::SalesOrder)            
        {

            //CB932 Changes None of the SO’s for the shipment has “Order processing status” = “Reprice required”
            select firstonly RecId from metSalesTable
            where metSalesTable.OrderProcessingStatus == METSalesOrderProcessingStatus::RepriceRequired
            exists join salesTable
                where salesTable.RecId == metSalesTable.SalesTable
            exists join shipmentLoadLines
                where shipmentLoadLines.OrderNum == salesTable.SalesId
            exists join shipmentLoadHeader
                where shipmentLoadHeader.ShipmentId == shipmentLoadLines.ShipmentId
                    && shipmentLoadHeader.LoadId    == this.LoadId;

            if (metSalesTable.RecId !=0)
            {
                return NoYes::No;
            }

            select firstonly crosscompany RecId from wmsPickingRoute
                where wmsPickingRoute.transType == InventTransType::Sales
                   && wmsPickingRoute.expeditionStatus != WMSExpeditionStatus::Complete
                   && wmsPickingRoute.expeditionStatus != WMSExpeditionStatus::Cancelled
                exists join shipmentLoadLines
                    where  wmsPickingRoute.transRefId == shipmentLoadLines.OrderNum
                    && wmsPickingRoute.DataAreaId != shipmentLoadLines.DataAreaId
                exists join shipmentLoadHeader
                    where shipmentLoadLines.ShipmentId == shipmentLoadHeader.ShipmentId &&
                          shipmentLoadHeader.LoadId == this.LoadId;

            if (wmsPickingRoute)
            {
                return NoYes::No;
            }

        }

        return NoYes::Yes;
    }

}

/// <summary>
/// Display method for pick complete
/// </summary>
/// <returns>Boolean</returns>
public display NoYesId displayPickComplete()
{
    WMSPickingRoute                     wmsPickingRoute;
    METSalesOrderShipmentLoadLines      shipmentLoadLines, salesOrderShipmentLoadLines;
    SalesLine                           salesLine;
    METSalesLine                        metSalesLine;
    SalesTable                          salesTable;
    METSalesTable                       metSalesTable;  
    InventTransferTable                 inventTransferTable;

    select firstonly RecId from wmsPickingRoute
        exists join shipmentLoadLines
        where   shipmentLoadLines.PickingListNum == wmsPickingRoute.pickingRouteID  &&
                shipmentLoadLines.ShipmentId == this.ShipmentId &&
                wmsPickingRoute.expeditionStatus != WMSExpeditionStatus::Complete;

    if (wmsPickingRoute.RecId != 0)
    {
        return NoYes::No;
    }
    else if (this.TransactionType == METOrderTransactionType::SalesOrder)
    {

        //CB932 Changes None of the SO’s for the shipment has “Order processing status” = “Reprice required”
        select firstonly RecId from metSalesTable
            where metSalesTable.OrderProcessingStatus == METSalesOrderProcessingStatus::RepriceRequired
            exists join salesTable
                where salesTable.RecId == metSalesTable.SalesTable
            exists join salesOrderShipmentLoadLines
                where salesOrderShipmentLoadLines.OrderNum  == salesTable.SalesId
                   && salesOrderShipmentLoadLines.ShipmentId == this.ShipmentId;

        if (metSalesTable.RecId !=0)
        {
            return NoYes::No;
        }

        select firstonly1 RecId from inventTransferTable
            where inventTransferTable.TransferStatus != InventTransferStatus::Received
            exists join metSalesLine
                where metSalesLine.TransferOrderNumber
                    && metSalesLine.TransferOrderNumber == inventTransferTable.TransferId
            exists join salesLine
                where salesLine.RecId == metSalesLine.SalesLine
            exists join salesOrderShipmentLoadLines
                where salesOrderShipmentLoadLines.OrderNum == salesLine.SalesId
                    && salesOrderShipmentLoadLines.ShipmentId == this.ShipmentId;


        if (inventTransferTable.RecId != 0)
        {
            return NoYes::No;
        }

        select firstonly crosscompany RecId from wmsPickingRoute
                where wmsPickingRoute.transType == InventTransType::Sales
                   && wmsPickingRoute.expeditionStatus != WMSExpeditionStatus::Complete
                   && wmsPickingRoute.expeditionStatus != WMSExpeditionStatus::Cancelled
            exists join salesOrderShipmentLoadLines
                where salesOrderShipmentLoadLines.ShipmentId == this.ShipmentId
                    && salesOrderShipmentLoadLines.OrderNum == wmsPickingRoute.transRefId
                    && wmsPickingRoute.DataAreaId != salesOrderShipmentLoadLines.DataAreaId;

        if (wmsPickingRoute.RecId)
        {
            return NoYes::No;
        }

        return NoYes::Yes;
    }
    else
    {
        return NoYes::Yes;
    }
}

