/// <summary>
/// Display method for shipping carrier
/// </summary>
/// <returns>Carrier code</returns>
[SysClientCacheDataMethodAttribute(true)]
public display TMSCarrierCode displayShippingCarrier()
{
    TMSCarrierCode                      carrierCode;
    TMSSalesTable                       tmsSalesTable;
    METSalesOrderShipmentLoadLines      shipmentLoadLines;
    TMSInventTransferTable              tmsTransferTable;

    if (this.TransactionType == METOrderTransactionType::SalesOrder)
    {
        select firstonly CarrierCode from tmsSalesTable
            exists join shipmentLoadLines
            order by OrderNum asc
                where tmsSalesTable.SalesId == shipmentLoadLines.OrderNum   &&
                    shipmentLoadLines.ShipmentId == this.ShipmentId;

        carrierCode = tmsSalesTable.CarrierCode;
    }
    else if (this.TransactionType == METOrderTransactionType::TransferOrder)
    {
        select firstonly CarrierCode from tmsTransferTable
            exists join shipmentLoadLines
            order by OrderNum asc
            where tmsTransferTable.TransferId == shipmentLoadLines.OrderNum
            && shipmentLoadLines.ShipmentId == this.ShipmentId;

        carrierCode = tmsTransferTable.CarrierCode;
    }
    return carrierCode;
}

/// <summary>
/// Find open load
/// </summary>
/// <param name = "_metRoute">Route</param>
/// <param name = "_confirmedDate">Confirmed date</param>
/// <param name = "_inventLocationId">Location Id</param>
/// <param name = "_transactionType">Transaction type</param>
/// <returns>METSalesOrderShipmentLoadHeader</returns>
public static METSalesOrderShipmentLoadHeader findOpenLoad(METRoute                     _metRoute,
                                                        SalesShippingDateConfirmed      _confirmedDate,
                                                        InventLocationId                _inventLocationId,
                                                        MetOrderTransactionType         _transactionType)
{
    METSalesOrderShipmentLoadHeader     metSalesOrderShipmentLoadHeader;

    if (_transactionType ==MetOrderTransactionType::SalesOrder)
    {
        select firstonly metSalesOrderShipmentLoadHeader
            where metSalesOrderShipmentLoadHeader.Route == _metRoute                    &&
                metSalesOrderShipmentLoadHeader.ConfirmedShipDate == _confirmedDate     &&
                metSalesOrderShipmentLoadHeader.Warehouse == _inventLocationId          &&
                metSalesOrderShipmentLoadHeader.LoadStatus == METLoadStatus::Open       &&
                metSalesOrderShipmentLoadHeader.TransactionType == _transactionType;
    }
    else
    {
        select firstonly metSalesOrderShipmentLoadHeader
            where metSalesOrderShipmentLoadHeader.Route == _metRoute                    &&
                metSalesOrderShipmentLoadHeader.ConfirmedShipDate == _confirmedDate     &&
                metSalesOrderShipmentLoadHeader.ToWarehouse == _inventLocationId          &&
                metSalesOrderShipmentLoadHeader.LoadStatus == METLoadStatus::Open       &&
                metSalesOrderShipmentLoadHeader.TransactionType == _transactionType;
    }
    return metSalesOrderShipmentLoadHeader;

}

/// <summary>
/// Validatation method for table
/// </summary>
/// <returns>Boolean value</returns>
public boolean validateWrite()
{
    METSalesOrderShipmentLoadHeader     shipmentLoadHeader;
    boolean ret;

    ret = super();

    if (this.TransactionType == METOrderTransactionType::SalesOrder)
    {
        select firstonly RecId from shipmentLoadHeader
            where shipmentLoadHeader.ConfirmedShipDate == this.ConfirmedShipDate    &&
                shipmentLoadHeader.CustAccount == this.CustAccount                  &&
                shipmentLoadHeader.Warehouse == this.Warehouse                      &&
                shipmentLoadHeader.Route == this.Route                              &&
                shipmentLoadHeader.RouteStopNum == this.RouteStopNum                &&
                shipmentLoadHeader.ShipmentId != this.ShipmentId                    &&
                shipmentLoadHeader.TransactionType == METOrderTransactionType::SalesOrder   &&
                shipmentLoadHeader.ShipmentStatus == MetShipmentStatus::Open;

        if (shipmentLoadHeader.RecId != 0)
        {
            ret = checkFailed(strFmt("@MET:ShipmentValidation", shipmentLoadHeader.ShipmentId));
        }
    }
    else
    {
        select firstonly RecId from shipmentLoadHeader
            where shipmentLoadHeader.ConfirmedShipDate == this.ConfirmedShipDate    &&
                shipmentLoadHeader.ToWarehouse == this.ToWarehouse                  &&
                shipmentLoadHeader.Warehouse == this.Warehouse                      &&
                shipmentLoadHeader.Route == this.Route                              &&
                shipmentLoadHeader.RouteStopNum == this.RouteStopNum                &&
                shipmentLoadHeader.ShipmentId != this.ShipmentId                    &&
                shipmentLoadHeader.TransactionType == METOrderTransactionType::TransferOrder   &&
                shipmentLoadHeader.ShipmentStatus == MetShipmentStatus::Open;

        if (shipmentLoadHeader.RecId != 0)
        {
            ret = checkFailed(strFmt("@MET:ShipmentValidation", shipmentLoadHeader.ShipmentId));
        }
    }

    return ret;
}

/// <summary>
/// Find load by recId
/// </summary>
/// <param name = "_recId">RecId reference</param>
/// <param name = "_forUpdate">boolean value</param>
/// <returns>METSalesOrderShipmentLoadHeader</returns>
public static METSalesOrderShipmentLoadHeader findByRecId(RefRecId      _recId, 
                                                        boolean         _forUpdate = false)
{
    METSalesOrderShipmentLoadHeader     metSalesOrderShipmentLoadHeader;

    if (_forUpdate)
    {
        metSalesOrderShipmentLoadHeader.selectForUpdate(true);
    }

    select firstonly metSalesOrderShipmentLoadHeader
        where metSalesOrderShipmentLoadHeader.RecId == _recId;

    return metSalesOrderShipmentLoadHeader;
}

/// <summary>
/// CB626_TMSEngineSOPackingSlip Find load by shipment Id
/// </summary>
/// <param name = "_shipmentId">SO finalisation shipment id</param>
/// <param name = "_forUpdate">Select reocrd for update</param>
/// <returns>METSalesOrderShipmentLoadHeader</returns>
public static METSalesOrderShipmentLoadHeader findByShipmentId(METShipmentId _shipmentId,
                                                               boolean       _forUpdate = false)
{
    METSalesOrderShipmentLoadHeader     metSalesOrderShipmentLoadHeader;

    if (_shipmentId)
    {
        if (_forUpdate)
        {
            metSalesOrderShipmentLoadHeader.selectForUpdate(true);
        }

        select firstonly metSalesOrderShipmentLoadHeader
                   where metSalesOrderShipmentLoadHeader.ShipmentId == _shipmentId;
    }
    return metSalesOrderShipmentLoadHeader;
}

/// <summary>
/// Update load status from shipment
/// </summary>
/// <param name = "_loadId">Load Id reference</param>
public static void updateLoadStatus(MetLoadId       _loadId)
{
    METSalesOrderShipmentLoadHeader         metSalesOrderShipmentLoadHeader;
    METSalesOrderShipmentLoadHeader         metSalesOrderShipmentLoadHeaderLoc;
    METSalesOrderShipmentLoadHeader         metSalesOrderShipmentLoadHeaderUpdate;
    MetLoadStatus                           metLoadStatusUpdate;

    select minof(ShipmentStatus) from metSalesOrderShipmentLoadHeader
        where metSalesOrderShipmentLoadHeader.LoadId == _loadId;

    switch (metSalesOrderShipmentLoadHeader.ShipmentStatus)
    {
        case MetShipmentStatus::Open :
            metLoadStatusUpdate = MetLoadStatus::Open;

            break;

        case MetShipmentStatus::Loaded :
            metLoadStatusUpdate = MetLoadStatus::Loaded;

            break;

        case MetShipmentStatus::Shipped :
            metLoadStatusUpdate = MetLoadStatus::Shipped;

            break;

        default :
            break;

    }

    select minof(LoadStatus) from metSalesOrderShipmentLoadHeaderLoc
        where metSalesOrderShipmentLoadHeaderLoc.LoadId == _loadId;

    if (metLoadStatusUpdate != metSalesOrderShipmentLoadHeaderLoc.LoadStatus)
    {
        metSalesOrderShipmentLoadHeaderUpdate.skipDataMethods(true);

        update_recordset metSalesOrderShipmentLoadHeaderUpdate
            setting LoadStatus = metLoadStatusUpdate
                where metSalesOrderShipmentLoadHeaderUpdate.LoadId == _loadId;

        info(strFmt("@MET:LoadUpdate", _loadId, metLoadStatusUpdate));
    }

}

/// <summary>
/// Update document status header
/// </summary>
/// <param name = "_shipmentStatus">Shipment status</param>
/// <param name = "_docStatus">Document status</param>
/// <param name = "_shipmentId">Shipment id</param>
public static void updateDocStatusInHeader(MetShipmentStatus _shipmentStatus, DocumentStatus _docStatus, WHSShipmentId _shipmentId)
{
    METSalesOrderShipmentLoadHeader     shipmentHeader;

    select firstonly forupdate shipmentHeader
        where shipmentHeader.ShipmentId == _shipmentId;

    if (shipmentHeader && shipmentHeader.ShipmentStatus != _shipmentStatus)
    {
        ttsbegin;

        shipmentHeader.ShipmentStatus   = _shipmentStatus;
        shipmentHeader.DocumentStatus   = _docStatus;
        shipmentHeader.update();
        shipmentHeader.reread();
        ttscommit;

        Info(strFmt("@MET:ShipmentUpdateMsg", shipmentHeader.ShipmentId, shipmentHeader.ShipmentStatus));
        METSalesOrderShipmentLoadHeader::updateLoadStatus(shipmentHeader.LoadId);
    }
}

/// <summary>
/// Update the route information on shipment header and lines
/// </summary>
/// <param name = "_confirmedShipDate">Confirmed ship date value</param>
/// <param name = "_route">Route value</param>
/// <param name = "_routeStopNum">Route stop num</param>
/// <returns>Set or ordernumbers</returns>
public Set updateRouteInformation(SalesShippingDateConfirmed   _confirmedShipDate,
                                METRoute                        _route,
                                METRouteStopNum                 _routeStopNum)
{
    METSalesOrderShipmentLoadLines      metSalesOrderShipmentLoadLines;
    Set         orderNumSet = new Set(Types::String);
    boolean     isUpdateNeeded = false;

    ttsbegin;

    this.skipDataMethods(true);

    if (_route && this.Route != _route)
    {
        this.Route = _route;
        isUpdateNeeded = true;
    }
    if (_routeStopNum && this.RouteStopNum != _routeStopNum)
    {
        this.RouteStopNum = _routeStopNum;
        isUpdateNeeded = true;
    }
    if (_confirmedShipDate && this.RouteStopNum != _routeStopNum)
    {
        this.ConfirmedShipDate = _confirmedShipDate;
        isUpdateNeeded = true;
    }

    if (isUpdateNeeded)
    {
        this.LoadId = ''; //Reset load id as route, route stop or date is getting changed.This will be filled in next step..

        //Either one value will always be available, hence not checking for update. Skipping update above if all three are blank.
        this.update();

        //Update recordset cannot be used as need to check what values are getting filled from dialogue
        while select metSalesOrderShipmentLoadLines
            group by OrderNum
            where metSalesOrderShipmentLoadLines.ShipmentId == this.ShipmentId
        {
            if (this.TransactionType == METOrderTransactionType::SalesOrder)
            {
                METSalesOrderShipmentLoadHeader::updateSalesTableAndShipment(metSalesOrderShipmentLoadLines.OrderNum, _confirmedShipDate, _route, _routeStopNum);
            }
            else
            {
                METSalesOrderShipmentLoadHeader::updateTransferOrderAndShipment(metSalesOrderShipmentLoadLines.OrderNum, _confirmedShipDate, _route, _routeStopNum);
            }

            orderNumSet.add(metSalesOrderShipmentLoadLines.OrderNum);
        }
    }

    ttscommit;

    return orderNumSet;
}

/// <summary>
/// Update sales order with new routes
/// </summary>
/// <param name = "_orderNum">Sales order</param>
/// <param name = "_confirmedShipDate">Confirm ship date</param>
/// <param name = "_route">Route value</param>
/// <param name = "_routeStopNum">Route stop num</param>
public static void updateSalesTableAndShipment(SalesId                         _orderNum,
                                            SalesShippingDateConfirmed      _confirmedShipDate,
                                            METRoute                        _route,
                                            METRouteStopNum                 _routeStopNum)
{
    SalesTable      salesTable;

    ttsbegin;

    salesTable = SalesTable::find(_orderNum, true);

    salesTable.skipDataMethods(true);

    if (_route)
    {
        salesTable.METRoute = _route;
    }
    if (_routeStopNum)
    {
        salesTable.METRouteStopNum = _routeStopNum;
    }
    if (_confirmedShipDate)
    {
        salesTable.ShippingDateConfirmed = _confirmedShipDate;
    }

    salesTable.SkipUpdate = true;
    //Either one value will always be available, hence not checking for update. Skipping update above if all three are blank.
    salesTable.update();

    ttscommit;
}

/// <summary>
/// Validation for shipment before going to shipped. 
/// </summary>
/// <returns>Boolean value</returns>
public boolean isValidShipmentToShipped()
{
    WMSPickingRoute                     wmsPickingRoute;
    METSalesOrderShipmentLoadLines      shipmentLoadLines;
    MetContainerTable   metContainerTable;
    boolean             ret = true;
    InventLocation      inventLocation = InventLocation::find(this.Warehouse);

    select firstonly RecId from metContainerTable
            where metContainerTable.ShipmentId == this.ShipmentId;

    if (metContainerTable.RecId == 0)
    {
        // CB729 Verify if the pre-check is allowed or not
        if ((this.TransactionType == METOrderTransactionType::SalesOrder && inventLocation.METIsContainerSalesFinalisation) || 
            (this.TransactionType == METOrderTransactionType::TransferOrder && inventLocation.METIsContainerTransferFinalisation))
        {
            Error(strFmt("@MET:ContainerNotAssociated", this.ShipmentId));
            ret = false;
        }

    }

    if (this.TransactionType == METOrderTransactionType::SalesOrder)
    {
        METCustTable   custTableLoc = METCustTable::find(this.CustAccount);

        const str export = "Export"; // CB731 - Multimodal Information - Build task

        if (custTableLoc.FinalizationDocument  == METFinalizationDocument::None)
        {
            warning(strFmt("@MET:DocumentNotSet", this.CustAccount, this.ShipmentId));
        }

        // CB731 - Multimodal Information - Build task
        if (custTableLoc.CustomerType == export && this.IsHazardousMaterial() && METHMIMMultimodalDG::findByShipment(this.ShipmentId).RecId == 0)
        { 
            warning(strFmt("@MET:METMultimodalNoShipmentWarning", this.ShipmentId));
        }

        if (ret)
        {
            ret = METSalesOrderProcessHelper::validateIntercompanyShipment(this.ShipmentId);
        }
    }

    if (this.isCCRPickDirectorFlagEnabled())
    {
        METSalesOrderShipmentLoadLines  mETSalesOrderShipmentLoadLines;

        select firstonly RecId, OrderNum from mETSalesOrderShipmentLoadLines
            where mETSalesOrderShipmentLoadLines.ShipmentId == this.ShipmentId
            && (mETSalesOrderShipmentLoadLines.OrderSplitGroup == METConstants::Tobacco
                || mETSalesOrderShipmentLoadLines.OrderSplitGroup == METConstants::TobaccoCSD)
            && mETSalesOrderShipmentLoadLines.CCRReceived == NoYes::No;

        if (mETSalesOrderShipmentLoadLines.RecId)
        {
            error(strfmt("@MET:CCRValidationErrorMsg", mETSalesOrderShipmentLoadLines.OrderNum));
            ret = false;
        }
    }

    while select OrderNum, ItemId from shipmentLoadLines
        where shipmentLoadLines.ShipmentId == this.ShipmentId
        exists join wmsPickingRoute
            where wmsPickingRoute.pickingRouteID == shipmentLoadLines.PickingListNum    &&
                wmsPickingRoute.expeditionStatus != WMSExpeditionStatus::Complete
    {
        if (this.TransactionType == METOrderTransactionType::SalesOrder)
        {
            ret = checkFailed(strFmt("@MET:SONotFullyPicked", shipmentLoadLines.OrderNum, shipmentLoadLines.ItemId));
        }
        else if (this.TransactionType == METOrderTransactionType::TransferOrder)
        {
            ret = checkFailed(strFmt("@MET:TONotFullPicked", shipmentLoadLines.OrderNum, shipmentLoadLines.ItemId));
        }
    }
    /*CB177&729_CustOnHoldStatus - start*/
    if (this.TransactionType == METOrderTransactionType::SalesOrder)
    {
        SalesTable                      salesTable;
        METSalesTable                   metSalesTable;
        METSalesOrderShipmentLoadLines  salesOrderShipmentLoadLines;

        select firstonly SalesId, RecId from salesTable
            where salesTable.CredManInCreditControl == NoYes::Yes
            exists join shipmentLoadLines
                where shipmentLoadLines.ShipmentId == this.ShipmentId
                    && salesTable.SalesId == shipmentLoadLines.OrderNum;

        if (salesTable.RecId != 0)
        {
            ret = checkFailed(strFmt("@MET:SOCredMgmt", salesTable.SalesId));
        }

        CustTable custTable = CustTable::find(this.CustAccount);

        if (METCustOnHoldStatusParameters::exists(custTable.Blocked))
        {
            ret = false;
            error(strFmt("@MET:CustShipmentOnHoldError", this.ShipmentId));
        }

        //CB932 Changes None of the SO’s for the shipment has “Order processing status” = “Reprice required”
        select firstonly RecId from metSalesTable
            where metSalesTable.OrderProcessingStatus == METSalesOrderProcessingStatus::RepriceRequired
            exists join salesTable
                where salesTable.RecId == metSalesTable.SalesTable
            exists join salesOrderShipmentLoadLines
                where salesOrderShipmentLoadLines.OrderNum  == salesTable.SalesId
                   && salesOrderShipmentLoadLines.ShipmentId == this.ShipmentId;

        if (metSalesTable.RecId !=0)
        {
            ret = checkFailed(strFmt("@MET:ShipmentConfirmationValidation", this.ShipmentId));
        }


    }
    /*CB177&729_CustOnHoldStatus - end*/

    return ret;
}

/// <summary>
/// method to check the flag is enable in warehouse
/// </summary>
/// <returns>boolean</returns>
/// CB231 - Container content report
public boolean isCCRPickDirectorFlagEnabled()
{
    InventLocation      inventLocation = InventLocation::find(this.Warehouse);

    if(inventLocation.METPickDirector == NoYes::Yes || inventLocation.METCCR == NoYes::Yes)
    {
        return true;
    }

    return false;
}

/// <summary>
/// method to check to check CCR data and update
/// </summary>
/// CB231 - Container content report
public void checkAndUpdateCCR()
{
    if(this.isCCRPickDirectorFlagEnabled())
    {
        METSalesOrderShipmentLoadLines      mETSalesOrderShipmentLoadLines;

        ttsbegin;
        while select forupdate mETSalesOrderShipmentLoadLines
            where mETSalesOrderShipmentLoadLines.ShipmentId == this.ShipmentId
        {
            NoYes   isSecurityTote  = this.checkSecurityTote(mETSalesOrderShipmentLoadLines);
            boolean isCCRReceived   = this.checkAndUpdateCCRTable(mETSalesOrderShipmentLoadLines.OrderNum, isSecurityTote);

            if(isCCRReceived)
            {
                mETSalesOrderShipmentLoadLines.CCRReceived = isCCRReceived;

                mETSalesOrderShipmentLoadLines.update();
            }
        }
        ttscommit;
    }
}

/// <summary>
/// method to check CCR table and Update if no SO found
/// </summary>
/// <param name = "_salesId">SalesId</param>
/// <param name = "_isSecurityToteEnabled">SalesId</param>
/// CB231 - Container content report
protected boolean checkAndUpdateCCRTable(SalesId _salesId, NoYes _isSecurityToteEnabled)
{
    METCCRTable     ccrTable;
    boolean         isCCRTableHasRecord = false;

    while select SalesId, ToteId from ccrTable group by SalesId, ToteId
        where ccrTable.SalesId == _salesId
    {
        isCCRTableHasRecord = true;

        this.checkAndUpdateTote(ccrTable.SalesId, ccrTable.ToteId, _isSecurityToteEnabled);
    }

    if(!isCCRTableHasRecord)
    {
        METCCRTable     ccrTableUpdate;
        WMSOrderTrans   wmsOrderTrans;
        METSalesLine    metSalesLine;
        SalesLine       salesLineLoc;

        select firstonly forupdate ccrTableUpdate
            exists join wmsOrderTrans
                where ccrTableUpdate.PickingRouteId == wmsOrderTrans.routeId            &&
                    wmsOrderTrans.inventTransType == InventTransType::TransferOrderShip 
            exists join salesLineLoc
                where salesLineLoc.SalesId == _salesId
            exists join metSalesLine
                where metSalesLine.SalesLine == salesLineLoc.RecId                      &&
                    wmsOrderTrans.inventTransRefId == metSalesLine.TransferOrderNumber;

        if (ccrTableUpdate.RecId != 0)
        {
            ttsbegin;

            ccrTableUpdate.SalesId = _salesId;
            ccrTableUpdate.update();
            ttscommit;

            isCCRTableHasRecord = true;

            this.checkAndUpdateTote(ccrTableUpdate.SalesId, ccrTableUpdate.ToteId, _isSecurityToteEnabled);
        }
    }
    return isCCRTableHasRecord;
}

/// <summary>
/// method to check and Update SalesId and ToteId in Tote table
/// </summary>
/// <param name = "_salesId">SalesId</param>
/// <param name = "_toteId">String20</param>
/// CB231 - Container content report
public void checkAndUpdateTote(SalesId _salesId, String20 _toteId, NoYesId _securityTote = NoYes::No)
{
    METTotes        totes;

    ttsbegin;
    select firstonly forupdate totes
        where totes.SalesId == _salesId &&
            totes.Tote == _toteId;

    if (totes.RecId == 0)
    {
        totes.SalesId       = _salesId;
        totes.Tote          = _toteId;
        totes.SecurityTote  = _securityTote;

        totes.insert();
    }
    else if(_securityTote == NoYes::Yes)
    {
        totes.SecurityTote  = _securityTote;

        totes.update();
    }
    ttscommit;

}

/// <summary>
/// method to check order split group for each line
/// </summary>
/// <param name = "_metSOShipmentLoadLines">METSalesOrderShipmentLoadLines</param>
/// <returns>NoYes</returns>
/// CB231 - Container content report
protected NoYes checkSecurityTote(METSalesOrderShipmentLoadLines _metSOShipmentLoadLines)
{
    METSplitGroupTable              splitGroupTable;
    METItemType                     itemType;
    NoYes                           isSecurityToteEnabled;

    select firstonly splitGroupTable
        where splitGroupTable.IsSecurityToteEnabled == NoYes::Yes &&
            splitGroupTable.SplitGroup == _metSOShipmentLoadLines.OrderSplitGroup;
    if(splitGroupTable)
    {
        isSecurityToteEnabled = NoYes::Yes;
    }

    select firstonly itemType
        where itemType.IsSecurityToteEnabled == NoYes::Yes &&
            itemType.ItemType == _metSOShipmentLoadLines.OrderSplitGroup;
    if(itemType)
    {
        isSecurityToteEnabled = NoYes::Yes;
    }

    return isSecurityToteEnabled;
}

/// <summary>
/// method to check order split group for each shipment
/// </summary>
/// <returns>NoYes</returns>
/// CB231 - Container content report
public NoYes checkShipmentSecurityTote()
{
    METSplitGroupTable              splitGroupTable;
    METItemType                     itemType;
    METSalesOrderShipmentLoadLines  metSOShipmentLoadLines;
    NoYes                           isSecurityToteEnabled;

    select firstonly splitGroupTable
        where splitGroupTable.IsSecurityToteEnabled == NoYes::Yes 
        join metSOShipmentLoadLines
            where metSOShipmentLoadLines.OrderSplitGroup == splitGroupTable.SplitGroup &&
                metSOShipmentLoadLines.shipmentid == this.ShipmentId;
    if(splitGroupTable)
    {
        isSecurityToteEnabled = NoYes::Yes;
    }

    select firstonly itemType
        where itemType.IsSecurityToteEnabled == NoYes::Yes
        join metSOShipmentLoadLines
            where metSOShipmentLoadLines.OrderSplitGroup == itemType.ItemType &&
                metSOShipmentLoadLines.shipmentid == this.ShipmentId;
    if(itemType)
    {
        isSecurityToteEnabled = NoYes::Yes;
    }

    return isSecurityToteEnabled;
}

/// <summary>
/// Update sales order with new routes
/// </summary>
/// <param name = "_transferId">Transfer order Id</param>
/// <param name = "_confirmedShipDate">Confirm ship date</param>
/// <param name = "_route">Route value</param>
/// <param name = "_routeStopNum">Route stop num</param>
public static void updateTransferOrderAndShipment(InventTransferId              _transferId,
                                                SalesShippingDateConfirmed      _confirmedShipDate,
                                                METRoute                        _route,
                                                METRouteStopNum                 _routeStopNum)
{
    InventTransferTable         inventTransferTable = InventTransferTable::find(_transferId, true);
    METInventTransferTableExt   metInventTransferTableExt = inventTransferTable.metInventTransferTableExt();

    ttsbegin;

    inventTransferTable.skipDataMethods(true);
    metInventTransferTableExt.skipDataMethods(true);

    metInventTransferTableExt.selectForUpdate(true);

    if (_route)
    {
        metInventTransferTableExt.Route = _route;
    }
    if (_routeStopNum)
    {
        metInventTransferTableExt.RouteStopNum = _routeStopNum;
    }

    if (_confirmedShipDate)
    {
        inventTransferTable.ShipDate = _confirmedShipDate;            
    }

    inventTransferTable.metPackMETInventTransferTableExt(metInventTransferTableExt);
    inventTransferTable.update();

    ttscommit;
}

/// <summary>
/// Update container charges
/// </summary>
/// <param name = "_shipmentId">Shipment Id</param>m>
public static void updateContainerCharges(WHSShipmentId _shipmentId)
{
    MetContainerTable containerTable;
    WHSContainerType containerType;

    while select containerTable
        where containerTable.ShipmentId == _shipmentId
        exists join containerType
        where containerType.METWHSContainerChargesMethod != METWHSContainerChargesMethod::None
           && containerType.ContainerTypeCode == containerTable.ContainerTypeCode
    {
        containerTable.updateSalesOrderNum();
    }
}

/// <summary>
///
/// </summary>
public MetShipmentId getShipmentId()
{
    str     shippingDateStr;

    shippingDateStr = date2Str
        (this.ConfirmedShipDate,
            321,
            DateDay::Digits2,
            DateSeparator::None,
            DateMonth::Digits2,
            DateSeparator::None,
            DateYear::Digits4);

    return strFmt("@MET:ShipmentStrFmt",
        this.Warehouse,
        this.CustAccount,
        this.Route,
        shippingDateStr);
}

/// <summary>
/// is Shipment containing Hazardous Material
/// </summary>
/// <returns>true/false</returns>
public boolean IsHazardousMaterial()
{
    METSalesOrderShipmentLoadLines           loadLines;
    InventTable                             inventTable;

    select firstonly RecId from inventTable
        exists join loadLines
            where loadLines.ItemId  == inventTable.ItemId       &&
                inventTable.HMIMIndicator == NoYes::Yes         &&
                loadLines.ShipmentId == this.ShipmentId;

    if (inventTable.RecId != 0)
    {
        return true;
    }
    else
    {
        return false;
    }
}

/// <summary>
/// Validate Transfer Order related to shipments are Received for confirmation.
/// </summary>
/// <returns> Boolean - true/ false </returns>
public boolean isSOLineRelatedTORecevied()
{
    METSalesOrderShipmentLoadLines  salesOrderShipmentLoadLines;
    SalesLine                       salesLine;
    METSalesLine                    metSalesLine;
    InventTransferTable             inventTransferTable;
    METSalesOrderShipmentLoadHeader salesOrderShipmentLoadHeader;
    boolean                         ret = true;

    select firstonly salesOrderShipmentLoadLines
        where salesOrderShipmentLoadLines.ShipmentId == this.ShipmentId
        join RecId from salesLine
            where salesLine.SalesId == salesOrderShipmentLoadLines.OrderNum
        join TransferOrderNumber from metSalesLine
            where metSalesLine.SalesLine == salesLine.RecId
                && metSalesLine.TransferOrderNumber
        join RecId from inventTransferTable
            where inventTransferTable.TransferId == metSalesLine.TransferOrderNumber
                && inventTransferTable.TransferStatus != InventTransferStatus::Received
        exists join  salesOrderShipmentLoadHeader
            where salesOrderShipmentLoadHeader.ShipmentId == salesOrderShipmentLoadLines.ShipmentId
                && salesOrderShipmentLoadHeader.TransactionType == METOrderTransactionType::SalesOrder;

    if(inventTransferTable.RecId != 0)
    {
        ret = checkFailed(strFmt("@MET:ShipmentTOValidationErrorMsg", salesOrderShipmentLoadLines.OrderNum, salesLine.LineNum, metSalesLine.TransferOrderNumber));
        return ret;
    }

    return ret;
}

/// <summary>
/// This method will process pickup advice agaisnt each RMA number
/// </summary>
/// <param name = "_custAccount">CustAccount</param>
/// <param name = "_loadId">LoadId</param>
public static void processsPickupAdvice(MetLoadId _loadId)
{
    SalesTable                          salesTable;
    METSalesTable                       metSalesTable;
    METSalesTable                       metSalesTableLoc;
    METSalesOrderShipmentLoadHeader     metSalesOrderShipmentLoadHeader;

    while select ReturnItemNum, RecId, SalesId from salesTable
        where salesTable.SalesType == SalesType::ReturnItem &&
            (salesTable.ReturnStatus == ReturnStatusHeader::Open ||
            salesTable.ReturnStatus == ReturnStatusHeader::Created)
        exists join metSalesTable
            where metSalesTable.SalesTable == salesTable.RecId &&
                metSalesTable.PickupAdviceLoadIdPrint == ''
        exists join metSalesOrderShipmentLoadHeader
            where metSalesOrderShipmentLoadHeader.CustAccount == salesTable.CustAccount &&
                metSalesOrderShipmentLoadHeader.LoadId == _loadId
    {
        ttsbegin;

        metSalesTableLoc = METSalesTable::findByRefRecId(salesTable.RecId, true);

        if (metSalesTableLoc.RecId)
        {
            metSalesTableLoc.PickupAdviceLoadIdPrint = _loadId;
            metSalesTableLoc.doUpdate(); //Using doUpdate to update only changed field flag and avoid dual write and other update business logic.
        }
        ttscommit;
    }
}

/// <summary>
/// Display method to show if sales order is in credit management
/// </summary>
public display CredManUsedInCreditManagement displayIsOrderInCredManagement()
{
    SalesTable salesTable;
    METSalesOrderShipmentLoadLines shipmentLoadLines;

    select firstonly1 RecId from salesTable
        exists join shipmentLoadLines
            where shipmentLoadLines.ShipmentId == this.ShipmentId
                && shipmentLoadLines.OrderNum == salesTable.SalesId
                && salesTable.CredManInCreditControl == NoYes::Yes;

    return salesTable.RecId != 0;
}

/// <summary>
/// Method will execute at the time of Update route to capture the current picked status for shipment
/// </summary>
/// <param name = "_conShipmentIds">shipments</param>
public static void updatePickComplete(MetShipmentId     shipmentId)
{
    METSalesOrderShipmentLoadHeader     metSalesOrderShipmentLoadHeader;

    ttsbegin;
    if (shipmentId)
    {
        metSalesOrderShipmentLoadHeader = METSalesOrderShipmentLoadHeader::findByShipmentId(shipmentId, true);

        if (metSalesOrderShipmentLoadHeader.RecId)
        {
            METSalesOrderShipmentLoadLines  metSalesOrderShipmentLoadLinesCheck;

            select firstonly RecId from metSalesOrderShipmentLoadLinesCheck
                where metSalesOrderShipmentLoadLinesCheck.ShipmentId == shipmentId
                    && metSalesOrderShipmentLoadLinesCheck.PickingListComplete == NoYes::No;

            if (metSalesOrderShipmentLoadLinesCheck.RecId == 0)
            {
                if (metSalesOrderShipmentLoadHeader.RecId)
                {
                    metSalesOrderShipmentLoadHeader.ShipmentPickComplete = NoYes::Yes;
                    metSalesOrderShipmentLoadHeader.update();
                }
            }
            else
            {
                if (metSalesOrderShipmentLoadHeader.RecId)
                {
                    metSalesOrderShipmentLoadHeader.ShipmentPickComplete = NoYes::No;
                    metSalesOrderShipmentLoadHeader.update();
                }
            }
        }
    }
    ttscommit;
}

/// <summary>
/// Clean shipment if no lines remaining after rearranging shipments
/// </summary>
/// <param name = "_conShipmentIds">ShipmentId reference</param>
public static void cleanShipmentIfNoLines(container    _conShipmentIds)
{
    METSalesOrderShipmentLoadHeader     metSalesOrderShipmentLoadHeader;
    METSalesOrderShipmentLoadLines      metSalesOrderShipmentLoadLine;
    int             i;
    METShipmentId   shipmentId;

    METProcMetrics procMetrics = METProcMetricsScope::current();

    if (procMetrics)
    {
        procMetrics.ttsBeginTrace();
        procMetrics.startDescriptionTime(4, "@MET:CleanShipNoLines");
    }

    for (i = 1; i <= conLen(_conShipmentIds); i++)
    {
        shipmentId = conPeek(_conShipmentIds, i);

        if (shipmentId)
        {
            delete_from metSalesOrderShipmentLoadHeader
                where metSalesOrderShipmentLoadHeader.ShipmentId == shipmentId
                    notexists join metSalesOrderShipmentLoadLine
                        where metSalesOrderShipmentLoadLine.ShipmentId == metSalesOrderShipmentLoadHeader.ShipmentId;

            if (metSalesOrderShipmentLoadHeader.RowCount() > 0)
            {
                info(strFmt("@MET:ShipmentDelete", shipmentId));
            }
        }
    }

    if (procMetrics)
    {
        procMetrics.incDescriptionCount(4, 1);
        procMetrics.ttsCommitTrace();
        procMetrics.endDescriptionTime(4);
    }
}

/// <summary>
/// Method will execute at the time of field modification to capture the current picked status for shipment
/// </summary>
/// <param name = "_fieldId">Fieldnum reference</param>
public void modifiedField(FieldId _fieldId)
{
    METSalesOrderShipmentLoadHeader     loadHeadrorig = this.orig();

    super(_fieldId);

    switch (_fieldId)
    {
        case fieldNum(METSalesOrderShipmentLoadHeader, SentToLaserNet) :

            if (loadHeadrorig.SentToLaserNet == NoYes::Yes && this.SentToLaserNet == NoYes::No)
            {
                this.DocumentPrintedCon = conNull();
            }

        break;

        default:
            break;
    }
}
